set-variable.value:
#[%dw 2.0
output application/json
---
{
  "aggregate": p('mongoDb-mdm.agendas.collection-pqr-agenda-tmr'),
  "pipeline": [
    {
      "\$match": {
        // Filtros de cabecera condicionales
        ( "customer_document_type": vars.parameters.CustomerIdType ) if (vars.parameters.CustomerIdType != null),
        ( "customer_document_number": vars.parameters.CustomerId ) if (vars.parameters.CustomerId != null),
        ( "order_number": vars.parameters.OrderNumber ) if (vars.parameters.OrderNumber != null),

        // El elemMatch solo se agrega si al menos un criterio del array viene
        ( "agendas_tmr": {
          "\$elemMatch": {
            ( "estado_agenda": vars.parameters.Status ) if (vars.parameters.Status != null),
            ( "fecha_inicio_agenda": {
              "\$gte": { "\$date": vars.parameters.StartDate },
              "\$lte": { "\$date": vars.parameters.EndDate }
            }) if (vars.parameters.StartDate != null and vars.parameters.EndDate != null)
          }
        }) if (vars.parameters.Status != null or vars.parameters.StartDate != null)
      }
    },
    {
      "\$addFields": {
        "agendas_tmr": {
          "\$filter": {
            "input": "\$agendas_tmr",
            "as": "item",
            "cond": {
              "\$and": [
                // Si Status es null, usamos true para que no filtre por ese campo
                if (vars.parameters.Status != null) { "\$eq": ["\$\$item.estado_agenda", vars.parameters.Status] } else true,
                // Si las fechas son null, usamos true
                if (vars.parameters.StartDate != null and vars.parameters.EndDate != null) {
                  "\$and": [
                    { "\$gte": ["\$\$item.fecha_inicio_agenda", { "\$date": vars.parameters.StartDate }] },
                    { "\$lte": ["\$\$item.fecha_inicio_agenda", { "\$date": vars.parameters.EndDate }] }
                  ]
                } else true
              ]
            }
          }
        }
      }
    },
    {
      "\$addFields": {
        "agendas_tmr": {
          "\$sortArray": { 
            "input": "\$agendas_tmr", 
            "sortBy": { "fecha_inicio_agenda": -1 } 
          }
        }
      }
    },
    { "\$skip": vars.parameters.OffSet as Number default 0 },
    { "\$limit": vars.parameters.Limit as Number default 10 }
  ],
  "cursor": {}
}]
